function makeAvatar(container,person){container.textContent=person?Array.from(person.name||'?')[0]:'♙';if(person?.avatar&&(/^(https:\/\/|data:image\/(webp|png|jpeg);base64,)/.test(person.avatar)||/^\/avatars\/[a-z0-9-]+\.svg$/.test(person.avatar))){const img=document.createElement('img');img.src=person.avatar;img.alt=person.name||'Supporter';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>img.remove(),{once:true});container.append(img)}}
