function drawProfiles(){document.querySelectorAll('.player-frame').forEach(e=>e.remove());const positions=['top-left','top-right','bottom-right','bottom-left'];state.teams.forEach((t,i)=>{const frame=document.createElement('button');frame.type='button';frame.className='player-frame '+positions[i]+' tier-'+supportTier(t.g||0)+(state.winner===i?' winner-frame':'')+((state.motion?.team??state.turn)===i?' current-frame':'');frame.style.setProperty('--team-color',colors[i]);frame.style.setProperty('--support-boost',Math.min(45,4+Math.log2(1+(t.g||0))*6)+'px');frame.id='player-frame-'+i;frame.setAttribute('aria-label',t.name+' supporters');frame.onclick=()=>showSupporters(i);const latest=t.latestSupporter||t.supporter||t.commenter;const person=latest||{name:'Demo profile',avatar:'/avatars/preview-'+(i+1)+'.svg'};const face=document.createElement('div');face.className='profile-face'+(!latest?' demo-profile':'');makeAvatar(face,person);if(latest){const crown=document.createElement('span');crown.className='leader-crown';crown.textContent='🎁';face.append(crown)}const country=document.createElement('div');country.className='player-country';country.textContent=entryName(t,i+1);if(rosterMode==='countries'&&inputMode==='gifts')country.prepend(countryFlag(t.flag,t.name));if((rosterMode==='teams'||inputMode==='comments')&&t.teamAvatar){const badge=document.createElement('img');badge.src=t.teamAvatar;badge.alt=t.name;badge.className='team-badge';country.prepend(badge)}const name=document.createElement('div');name.className='player-name';name.textContent=t.active===false?'ELIMINATED':latest?.name||'DEMO PROFILE';const gift=document.createElement('div');gift.className='player-gift'+(inputMode==='comments'?' numeric-team-badge':'');const icon=document.createElement('span');icon.className='gift-symbol';icon.textContent=inputMode==='comments'?String(i+1):giftLabel(i).symbol;if(inputMode==='gifts'&&['5655','5269','6064','5827'].includes(giftMap[i])){const image=document.createElement('img');image.src='/gifts/'+giftMap[i]+'.png';image.alt=giftLabel(i).name;image.addEventListener('error',()=>image.remove(),{once:true});icon.textContent='';icon.append(image)}const label=document.createElement('span');if(inputMode==='comments')label.textContent='TEAM '+(i+1);else{const title=document.createElement('strong');title.className='gift-name';title.textContent=giftLabel(i).name==='Ice Cream Cone'?'Ice Cream':giftLabel(i).name;const score=document.createElement('b');score.className='gift-count';score.textContent=String(t.g||0);label.append(title,score)}gift.append(icon,label);const comment=document.createElement('span');comment.className='play-code';comment.textContent=inputMode==='gifts'?(state.winner===i?'🏆 WINNER':tierLabel(t.g||0)+' · 1 COIN GIFT'):'COMMENT '+(i+1);frame.append(comment);const total=document.createElement('span');total.className='supporter-total';if(t.g>0)total.textContent=(t.supporters?.length||1)+' SUPPORTERS · TOP '+(t.supporter?.gifts||0);else{total.textContent=(inputMode==='gifts'?'AUTO DICE · 8 ROLLS PER COUNTRY':'FREE TO PLAY');if(t.noGiftTurns)total.classList.add('elimination-warning')}const votes=document.createElement('span');votes.className='country-votes';votes.textContent='💬 '+(t.requests||0);frame.append(face,country,name,total,gift,votes);document.querySelector('.board-wrap').append(frame)});
const mapping=$('giftMappings');if(!mapping.contains(document.activeElement)){mapping.replaceChildren();state.teams.forEach((t,i)=>{const row=document.createElement('label');row.className='map-row';const label=document.createElement('span');label.className='map-label';label.textContent=entryName(t,i+1)+' · '+giftLabel(i).symbol+' '+giftLabel(i).name;const input=document.createElement('select');input.id='giftId'+i;input.setAttribute('aria-label',t.name+' one coin gift');oneCoinGifts.forEach(g=>{const option=document.createElement('option');option.value=g.id;option.textContent=g.symbol+' '+g.name+' · 1 coin';option.disabled=giftMap.some((id,j)=>j!==i&&id===g.id);input.append(option)});input.value=giftMap[i]||'';input.onchange=()=>{const value=input.value.trim();if(!oneCoinGifts.some(g=>g.id===value)||giftMap.some((v,j)=>j!==i&&v===value)){message('Every country needs a unique numeric gift ID.');input.value=giftMap[i]||'';return}giftMap[i]=value;const p=oneCoinGifts.find(p=>p.id===value);if(p)state.teams[i].gift=p.symbol+' '+p.name;queueSync()};row.append(label,input);mapping.append(row)})}
$('queueAdmin').replaceChildren();state.queue.forEach(t=>{const row=document.createElement('div');row.className='queue-admin map-row';const label=document.createElement('span');label.className='request-label';label.textContent=t.requestId+' · '+entryName(t,t.requestId)+' ('+(t.requests||0)+')';const minus=document.createElement('button'),plus=document.createElement('button');minus.textContent='−';plus.textContent='+';minus.onclick=()=>command('queue-adjust',{requestId:t.requestId,delta:-1});plus.onclick=()=>command('queue-adjust',{requestId:t.requestId,delta:1});row.append(label,minus,plus);$('queueAdmin').append(row)})}
