function remote(m){if(ready&&m.revision===serverRevision){renderConnection(m);renderLikers(m.snapshot.likers||[],m.snapshot.state.teams);drawTurnStatus();return}applyingRemote=true;giftHighlights=m.snapshot.giftHighlights||[];globalGifters=m.snapshot.gifters||[];renderLikers(m.snapshot.likers||[],m.snapshot.state.teams);renderConnection(m);isDemoRunning=!!m.demoRunning;$('demoBanner').hidden=!isDemoRunning;$('startDemo').hidden=isDemoRunning;$('stopDemo').hidden=!isDemoRunning;serverRevision=m.revision;const s=m.snapshot;automation=s.automation||automation;waitingGiftMap=s.waitingGiftMap||waitingGiftMap;railSide=['left','right','split'].includes(s.display?.railSide)?s.display.railSide:'split';document.querySelector('main').dataset.railSide=railSide;updateAutomationControls();rosterMode=s.rosterMode||'countries';inputMode=s.inputMode==='gifts'?'gifts':'comments';state=s.state;config=s.config;giftMap=s.giftMap;likeCount=s.likes||0;fans=s.fans||[];render();$('likes').textContent=compactCount(likeCount);const d=s.display||{};$('effects').checked=d.effects!==false;$('sound').checked=!!d.sound;$('volume').value=d.volume??20;document.body.classList.toggle('portrait',d.portrait!==false);updateModeLabels();updateVisiblePlayMode();renderRosterEditor();if(d.bg){document.body.style.setProperty('--backdrop',d.bg);localStorage.setItem('ludo-bg',d.bg)}document.querySelector('main').style.maxWidth=(Number(d.width||100)*14.4)+'px';$('liveStatus').textContent=m.status;$('liveUsername').placeholder=m.username?'@'+m.username:'نام حساب تیک‌تاک بدون @';ready=true;lastSynced=JSON.stringify(collect());applyingRemote=false}
