function openSocket(){clearTimeout(retryTimer);socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/events');socket.onopen=authenticate;socket.onmessage=event=>{try{const m=JSON.parse(event.data);if(m.type==='snapshot')remote(m);else if(m.type==='auth'){admin=m.ok;document.body.classList.toggle('can-manage',admin);$('authBox').hidden=admin;$('adminTools').hidden=!admin;if(admin){const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));sessionStorage.setItem('ludo-admin',key);$('adminKey').value='';message('Management panel ready. Gifts and countries are preconfigured.')}else message('Invalid management key.')}else if(m.type==='effect'){effect(m.symbol);if(Number.isInteger(m.corner))$('player-frame-'+m.corner)?.classList.add('new-gift')}else if(m.type==='like-reaction'){edgeHearts(m.count);flyCountryHearts(m.corner,m.count)}else if(m.type==='last-gift')$('lastLiveGift').textContent='آخرین گیفت: '+m.giftName+' · ID '+m.giftId;else if(m.type==='notice'||m.type==='error')message(m.message)}catch(error){console.warn('Live update failed:',error.message)}};socket.onclose=()=>{admin=false;document.body.classList.remove('can-manage');$('liveStatus').textContent='ارتباط سرور قطع شد؛ تلاش مجدد…';retryTimer=setTimeout(openSocket,3000)}}
