const rosterTools=document.createElement('details');rosterTools.id='rosterTools';rosterTools.open=true;rosterTools.innerHTML=`<summary>نام و عکس تیم‌ها</summary><div class="map-row"><label>حالت صفحه <select id="rosterMode"><option value="countries">کشورها · Countries</option><option value="teams">تیم / افراد · Teams</option></select></label><label>روش حرکت <select id="inputMode"><option value="comments">کامنت رایگان · Free comments</option><option value="gifts">تاس خودکار کشورها · Auto dice</option></select></label></div><p>کامنت‌های 1 تا 4 مهره‌های داخل میدان را حرکت می‌دهند. درخواست ورود تیم‌های منتظر با شماره‌های 5 تا 14 است. در حالت تیمی، حرکت با کامنت است؛ حذف تیم فقط با دکمهٔ حذف انجام می‌شود.</p><div class="map-row"><select id="rosterEntry" aria-label="انتخاب تیم"></select><input id="rosterName" placeholder="English team or person name" maxlength="32" aria-label="Team name"><input id="rosterFlag" placeholder="🇦🇫" aria-label="Flag" maxlength="12"></div><div class="map-row"><label>عکس فرد / تیم <input id="rosterPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="saveRoster">ذخیره نام و عکس</button><button id="clearRosterPhoto">حذف عکس</button><button id="removeRosterEntry" class="danger">حذف تیم / کشور انتخاب‌شده</button><button id="restoreRosterEntry">برگرداندن تیم حذف‌شده</button></div><img id="rosterPreview" class="roster-preview" alt="Team picture preview" hidden><p>نام نمایشی را انگلیسی وارد کنید. عکس تیم جای بیرق می‌آید؛ عکس بزرگ داخل فریم همچنان حامی برتر است. گیفت هر گوشه حداکثر ۱ کوین و مستقل از کشور یا تیم جایگزین است.</p>`;
$('adminTools').prepend(rosterTools);let draftPhoto=undefined;
function selectedEntry(){const [kind,key]=$('rosterEntry').value.split(':');return kind==='active'?state.teams[Number(key)]:state.queue.find(t=>t.requestId===Number(key))}
function fillRosterDraft(){const t=selectedEntry();if(!t)return;draftPhoto=undefined;$('rosterName').value=entryName(t,$('rosterEntry').value.startsWith('active:')?Number($('rosterEntry').value.split(':')[1])+1:t.requestId);$('rosterFlag').value=t.flag||'';$('rosterPhoto').value='';$('rosterPreview').hidden=!t.teamAvatar;if(t.teamAvatar)$('rosterPreview').src=t.teamAvatar}
function renderRosterEditor(){if(!$('rosterEntry'))return;const select=$('rosterEntry'),prior=select.value;if(rosterTools.contains(document.activeElement))return;select.replaceChildren();state.teams.forEach((t,i)=>{const o=document.createElement('option');o.value='active:'+i;o.textContent=(t.active===false?'حذف شده · ':'')+'TEAM '+(i+1)+' · '+entryName(t,i+1);select.append(o)});state.queue.forEach(t=>{const o=document.createElement('option');o.value='queue:'+t.requestId;o.textContent='WAITING '+t.requestId+' · '+entryName(t,t.requestId);select.append(o)});if([...select.options].some(o=>o.value===prior))select.value=prior;if(!prior||!selectedEntry())fillRosterDraft();$('rosterMode').value=rosterMode;$('inputMode').value=inputMode}
$('rosterEntry').onchange=fillRosterDraft;$('rosterMode').onchange=()=>{rosterMode=$('rosterMode').value;render();updateModeLabels();queueSync()};$('inputMode').onchange=()=>command('set-input-mode',{inputMode:$('inputMode').value});
$('rosterPhoto').onchange=async()=>{const file=$('rosterPhoto').files[0];if(!file)return;if(file.size>5*1024*1024){message('Choose an image smaller than 5 MB.');return}try{const img=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const ctx=canvas.getContext('2d');const side=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,160,160);draftPhoto=canvas.toDataURL('image/webp',.75);img.close();if(draftPhoto.length>40000){message('Image is too large. Choose a simpler image.');draftPhoto=undefined;return}$('rosterPreview').src=draftPhoto;$('rosterPreview').hidden=false}catch{message('This image could not be opened. Use JPG, PNG or WebP.')}};
$('clearRosterPhoto').onclick=()=>{draftPhoto='';$('rosterPreview').hidden=true};$('saveRoster').onclick=()=>{const t=selectedEntry(),name=$('rosterName').value.trim();if(!t)return;if(!name||/[^\x20-\x7E]/.test(name)){message('Enter an English display name.');return}if(inputMode==='comments')t.teamName=name;else t.name=name;t.flag=$('rosterFlag').value.trim()||'🏳';if(draftPhoto!==undefined)t.teamAvatar=draftPhoto;config=state.teams.map(t=>[t.flag,t.name,t.gift].join('|')).concat(state.queue.slice().sort((a,b)=>a.requestId-b.requestId).map(t=>[t.flag,t.name].join('|'))).join('\n');draftPhoto=undefined;render();queueSync();message('Team name and picture saved.');fillRosterDraft()};
function updateModeLabels(){const team=rosterMode==='teams'||inputMode==='comments';const heading=document.querySelector('.live-heading h1');heading.textContent=team?'Back your team.':'Lucky Nations.';document.querySelector('.live-heading .eyebrow').textContent=team?'FOUR TEAMS. ONE ARENA.':'FOUR COUNTRIES. ONE ARENA.';document.querySelector('.live-heading p').textContent=inputMode==='gifts'?'Watch the dice spin. Every gift adds one point.':'Play for free. Comment 1, 2, 3 or 4 to move.';const arenaHeader=document.querySelector('.arena-head');arenaHeader.children[0].textContent=(team?'TEAM LUDO':'COUNTRY DICE')+' BATTLE';arenaHeader.children[1].textContent=inputMode==='gifts'?'AUTO DICE · 8 ROLLS PER COUNTRY':'FREE PLAY · COMMENT 1–4';document.querySelector('.queue-hint').textContent='Comment the number to request entry. Top 5 shown.';document.querySelector('.arena-caption').children[0].textContent='♛ TOP GIFTER IN EVERY FRAME';$('rosterMode').value=rosterMode;$('inputMode').value=inputMode}
let lastMotionId=null;
function animateMove(){const m=state.motion;if(!m||m.phase!=='move'||m.pawn<0||m.id===lastMotionId)return;lastMotionId=m.id;if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const el=document.querySelector(`.pawn[data-team="${m.team}"][data-pawn="${m.pawn}"]`);if(!el?.animate)return;const cellAt=p=>p<52?route[(p+m.team*13)%52]:p<58?lanes[m.team][p-52]:[7,7];const end=cellAt(m.to),points=[];const cellSize=$('board').getBoundingClientRect().width/15;if(m.from<0){const home=[[2.5,2.5],[2.5,11.5],[11.5,11.5],[11.5,2.5]][m.team];points.push({transform:`translate(${(home[1]-end[1])*cellSize}px,${(home[0]-end[0])*cellSize}px) scale(1.15)`})}for(let p=Math.max(0,m.from);p<=m.to;p++){const c=cellAt(p);points.push({transform:`translate(${(c[1]-end[1])*cellSize}px,${(c[0]-end[0])*cellSize}px) scale(1.12)`})}points.push({transform:'translate(0,-3px) scale(1)'});el.animate(points,{duration:850,easing:'linear'});el.style.zIndex='12'}
renderRosterEditor();updateModeLabels();

const demoBanner=document.createElement('div');demoBanner.id='demoBanner';demoBanner.className='demo-banner';demoBanner.hidden=true;demoBanner.innerHTML='<span>DEMO · NO REAL GIFTS · FREE PREVIEW</span><button id="stopDemoBanner">Stop demo</button>';document.querySelector('.site-header').after(demoBanner);$('startDemo').onclick=()=>{command('demo-start');document.body.classList.add('broadcast');window.scrollTo?.({top:0,behavior:'smooth'})};$('stopDemo').onclick=()=>command('demo-stop');$('stopDemoBanner').onclick=()=>{command('demo-stop');document.body.classList.remove('broadcast')};

function fitMobileLive(){const main=document.querySelector('main');main.style.transform='';main.style.marginBottom='';if(!document.body.classList.contains('broadcast'))return;const demo=streamOutput||$('demoBanner').hidden?0:$('demoBanner').getBoundingClientRect().height+10;const gap=streamOutput?0:12;const available=Math.max(180,(window.visualViewport?.height||window.innerHeight)-demo-gap);const scale=Math.max(.1,Math.min((window.innerWidth-gap)/1080,available/1920));main.style.transform='scale('+scale+')';main.style.marginBottom='-'+Math.round(1920*(1-scale))+'px'}
const mobileView=window.matchMedia?.('(max-width: 780px)');if(mobileView?.matches){document.body.classList.add('broadcast');requestAnimationFrame(fitMobileLive)}
window.addEventListener('resize',fitMobileLive);window.visualViewport?.addEventListener('resize',fitMobileLive);new MutationObserver(()=>{if(streamOutput&&!document.body.classList.contains('broadcast'))document.body.classList.add('broadcast');requestAnimationFrame(fitMobileLive)}).observe(document.body,{attributes:true,attributeFilter:['class']});
