const diagnosticsBox=document.createElement('div');diagnosticsBox.id='connectionDetails';diagnosticsBox.className='connection-details';$('liveStatus').after(diagnosticsBox);$('liveUsername').placeholder='Any TikTok username · no login required';
function renderConnection(m){const box=$('connectionDetails');if(!box)return;box.replaceChildren();const c=m.connection||{};const line=document.createElement('p');line.textContent='حساب: '+(m.username?'@'+m.username:'انتخاب نشده')+' · وضعیت: '+(c.status||'disconnected')+' · تلاش: '+(c.retryAttempt||0);box.append(line);const method=document.createElement('p');method.textContent='فقط یوزرنیم هر حساب در حال لایو؛ بدون ورود، رمز، کوکی یا کلید API تیک‌تاک.';box.append(method);if(c.diagnostics?.length){const d=document.createElement('p');d.className='connection-error';d.textContent=c.diagnostics.map(d=>d.reason+(d.httpStatus?' HTTP '+d.httpStatus:'')+(d.route?' / '+d.route:'')).join(' · ');box.append(d)}if(c.retryAt){const wait=document.createElement('p');wait.textContent='تلاش بعدی: '+Math.max(0,Math.ceil((c.retryAt-Date.now())/1000))+' ثانیه دیگر';box.append(wait)}const traffic=document.createElement('p');traffic.textContent='دریافت واقعی — کامنت: '+(m.traffic?.comments||0)+' · لایک: '+(m.traffic?.likes||0)+' · گیفت: '+(m.traffic?.gifts||0);box.append(traffic);$('connectLive').disabled=c.status==='connecting';$('connectLive').textContent=c.status==='connecting'?'در حال اتصال…':'اتصال با یوزرنیم'}
const likerRail=document.createElement('aside');likerRail.id='likerRail';likerRail.className='liker-rail';likerRail.setAttribute('aria-label','Live likes');const gifterRail=document.createElement('aside');gifterRail.id='gifterRail';gifterRail.className='liker-rail gifter-rail';gifterRail.setAttribute('aria-label','Live gift supporters');document.querySelector('main').append(likerRail,gifterRail);const leftEdge=document.createElement('div'),rightEdge=document.createElement('div');leftEdge.className='reaction-edge edge-left';rightEdge.className='reaction-edge edge-right';leftEdge.setAttribute('aria-hidden','true');rightEdge.setAttribute('aria-hidden','true');document.querySelector('main').append(leftEdge,rightEdge);
function compactCount(value){const n=Math.max(0,Number(value)||0);return n>=1000000?(Math.floor(n/100000)/10)+'m':n>=1000?(Math.floor(n/100)/10)+'k':String(n)}
let audienceRenderKey='';
function renderLikers(people,teams=state.teams){
 const likes=$('likerRail'),gifts=$('gifterRail');if(!likes||!gifts)return;
 const renderKey=JSON.stringify([people,globalGifters,giftHighlights[0],globalGifters.length?null:teams?.map(t=>t.supporters)]);
 if(renderKey===audienceRenderKey){const timer=gifts.querySelector('.spotlight-timer');if(timer&&giftHighlights[0])timer.textContent=Math.max(0,Math.ceil((giftHighlights[0].until-Date.now())/1000))+'s SPOTLIGHT';return}
 audienceRenderKey=renderKey;likes.replaceChildren();gifts.replaceChildren();
 const ranked=(people.length?[...people]:[1,2,3].map(n=>({id:'preview-like-'+n,name:['Alex','Mia','Noah'][n-1],avatar:'/avatars/preview-'+(n+4)+'.svg',likes:0,isDemo:true}))).sort((a,b)=>b.likes-a.likes);
 const donors=new Map();for(const t of teams||[])for(const d of t.supporters||[]){const prior=donors.get(d.id||d.name);donors.set(d.id||d.name,{...d,gifts:(prior?.gifts||0)+d.gifts})}
 let top=(globalGifters.length?[...globalGifters]:[...donors.values()]).sort((a,b)=>b.gifts-a.gifts);if(!top.length)top=[1,2,3].map(n=>({id:'preview-gift-'+n,name:['Liam','Ava','Leo'][n-1],avatar:'/avatars/preview-'+n+'.svg',gifts:0,isDemo:true}));
 const highlighted=giftHighlights[0];
 function title(rail,text){const label=document.createElement('span');label.className='liker-title';label.textContent=text;rail.append(label)}
 function card(rail,p,kind,featured,follow){const el=document.createElement('div');el.className='liker-card '+(p.tier||'basic')+' '+kind+(featured?' rail-featured':' rail-compact')+(p.isDemo?' demo-profile':'');const face=document.createElement('div');face.className='liker-face';makeAvatar(face,p);const name=document.createElement('strong');name.textContent=p.name;const count=document.createElement('small');count.textContent=(kind==='gifter'?'🎁 ':'♥ ')+compactCount(kind==='gifter'?p.gifts:p.likes);el.append(face,name,count);if(p.isDemo){const demo=document.createElement('span');demo.className='audience-demo-label';demo.textContent='DEMO';el.append(demo)}if(follow){const handle=String(p.uniqueId||'').replace(/^@/,'');const link=document.createElement(/^[A-Za-z0-9._]{1,32}$/.test(handle)?'a':'span');link.className='follow-profile';link.textContent='Follow +';if(link.tagName==='A'){link.href='https://www.tiktok.com/@'+encodeURIComponent(handle);link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label','Open '+p.name+' TikTok profile to follow')}else{link.classList.add('unavailable');link.setAttribute('aria-disabled','true');link.title='TikTok username not received yet'}el.append(link)}rail.append(el)}
 title(likes,'♥ TOP LIKERS');ranked.slice(0,3).forEach((p,i)=>card(likes,p,'liker',i===0,i===0));
 title(gifts,highlighted?'🎁 GIFT SPOTLIGHT':'🎁 TOP GIFTERS');const featured=highlighted||top[0];if(featured)card(gifts,featured,'gifter',true,true);if(highlighted){const timer=document.createElement('span');timer.className='spotlight-timer';timer.textContent=Math.max(0,Math.ceil((highlighted.until-Date.now())/1000))+'s SPOTLIGHT';gifts.append(timer)}top.filter(p=>p.id!==featured?.id).slice(0,2).forEach(p=>card(gifts,p,'gifter',false,false));likes.hidden=false;gifts.hidden=false;
}

let reactionSide=0;function edgeHearts(count=1){for(let i=0;i<Math.min(6,Math.max(2,Math.ceil(Math.log10(count+1)*2)));i++){const el=document.createElement('span');el.className='edge-heart';el.textContent=i%3===0?'♡':'♥';el.style.left=(15+Math.random()*40)+'%';el.style.fontSize=(22+Math.random()*24)+'px';el.style.animationDelay=i*.12+'s';(reactionSide++%2?leftEdge:rightEdge).append(el);setTimeout(()=>el.remove(),3300)}}

function flyCountryHearts(corner,count){if(!Number.isInteger(corner)||corner<0||corner>3)return;const target=$('player-frame-'+corner),stage=document.querySelector('main');if(!target||!stage)return;const from=($('likerRail')?.querySelector('.rail-featured .liker-face')||$('likerRail')),a=from?.getBoundingClientRect(),b=target.getBoundingClientRect(),base=stage.getBoundingClientRect();if(!a)return;const scaleX=stage.offsetWidth/base.width,scaleY=stage.offsetHeight/base.height;target.classList.remove('like-burst');void target.offsetWidth;target.classList.add('like-burst');setTimeout(()=>target.classList.remove('like-burst'),1400);for(let i=0;i<Math.min(7,Math.max(3,Math.ceil(Math.log2(count+1))));i++){const heart=document.createElement('span');heart.className='country-flying-heart';heart.textContent='♥';heart.style.left=((a.left+a.width/2-base.left)*scaleX)+'px';heart.style.top=((a.top+a.height/2-base.top)*scaleY)+'px';stage.append(heart);const dx=(b.left+b.width/2-a.left-a.width/2)*scaleX,dy=(b.top+b.height/2-a.top-a.height/2)*scaleY;heart.animate([{transform:'translate(0,0) scale(.55)',opacity:0},{transform:'translate('+dx*.35+'px,'+(dy*.35-65-i*10)+'px) scale(1.25)',opacity:1},{transform:'translate('+dx+'px,'+dy+'px) scale(.4)',opacity:0}],{duration:850+i*90,delay:i*65,easing:'ease-in-out'}).finished.finally(()=>heart.remove())}}
const outputLinks=document.createElement('div');outputLinks.className='stream-link-help';outputLinks.innerHTML='<strong>لینک مخصوص نمایش در لایو</strong><p>این لینک را در منبع Browser / Website بگذارید؛ لینک مدیریت برای نمایش روی لایو نیست.</p><div class="map-row"><input id="liveScreenURL" readonly aria-label="Live screen URL"><button id="copyLiveScreen">کپی لینک نمایش</button></div><p>Width: 1080 · Height: 1920 · Fit / Contain · Crop: 0</p>';$('adminTools').prepend(outputLinks);$('liveScreenURL').value=location.origin+'/screen';$('copyLiveScreen').onclick=async()=>{try{await navigator.clipboard.writeText($('liveScreenURL').value);message('Live screen link copied.')}catch{$('liveScreenURL').select();message('Select and copy the live screen link.')}};if(streamOutput){document.documentElement.classList.add('stream-output');document.body.classList.add('broadcast');requestAnimationFrame(fitMobileLive)}

const playModeBox=document.createElement('section');playModeBox.className='visible-play-mode';playModeBox.innerHTML='<strong>انتخاب بازی: تیم‌ها یا کشورها</strong><p>از همین‌جا روش بازی را انتخاب کنید:</p><div class="play-mode-buttons"><button id="playWithNumbers" type="button"><b>123</b><span>عدد — تیم‌ها</span><small>رایگان · 1، 2، 3، 4</small></button><button id="playWithGifts" type="button"><b>🎲</b><span>تاس خودکار — کشورها</span><small>بدون نیاز به گیفت · حمایت ۱ کوینی</small></button></div><p id="currentPlayMode" role="status"></p>';$('adminTools').prepend(playModeBox);const visibleModeButtons={comments:$('playWithNumbers'),gifts:$('playWithGifts')};for(const [value,button] of Object.entries(visibleModeButtons))button.onclick=()=>{command('set-input-mode',{inputMode:value});$('currentPlayMode').textContent='در حال ذخیرهٔ روش بازی…'};function updateVisiblePlayMode(){if(!$('currentPlayMode'))return;for(const [value,button] of Object.entries(visibleModeButtons)){button.classList.toggle('is-selected',value===inputMode);button.setAttribute('aria-pressed',String(value===inputMode))}$('currentPlayMode').textContent='روش فعلی: '+({comments:'عدد — تیم‌ها؛ رایگان',gifts:'تاس خودکار — کشورها'}[inputMode]||inputMode)}updateVisiblePlayMode();if(!streamOutput&&new URLSearchParams(location.search).get('panel')==='1'){document.body.classList.remove('broadcast');window.scrollTo?.({top:0})}

// A single audio context per display; browsers may require one interaction first.
var gameAudio,heardRoll,heardMove;
function unlockGameAudio(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;gameAudio ||=new Audio();gameAudio.resume().catch(()=>{})}catch{}}
document.addEventListener('pointerdown',unlockGameAudio,{once:true});document.addEventListener('keydown',unlockGameAudio,{once:true});
function gameTone(frequency,at,duration,type='sine'){if(gameAudio?.state!=='running')return;const osc=gameAudio.createOscillator(),gain=gameAudio.createGain(),start=gameAudio.currentTime+at;osc.type=type;osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(0.0001,start);gain.gain.exponentialRampToValueAtTime(Math.max(.001,Number($('volume').value??20)/350),start+.008);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain);gain.connect(gameAudio.destination);osc.start(start);osc.stop(start+duration+.02)}
function playGameMotion(){const m=state.motion;if(!m)return;if(m.phase==='roll'&&heardRoll!==m.id){heardRoll=m.id;for(let n=0;n<(m.kind==='dice'?18:7);n++)gameTone(180+n%3*95,n*(m.kind==='dice'?.075:.07),.055,'triangle')}if(m.phase==='move'&&heardMove!==m.id){heardMove=m.id;const steps=m.kind==='dice'?m.dice:m.pawn<0?0:m.from<0?1:Math.max(1,m.to-m.from);for(let n=0;n<steps;n++)gameTone(520+n*45,n*.85/steps,.085);if(state.winner===m.team)[660,830,990,1320].forEach((f,n)=>gameTone(f,n*.17,.35))}}

// Owner controls mutate only the requested setting; the board keeps its position.
const automationBox=document.createElement('section');automationBox.className='automation-controls';automationBox.innerHTML=`<strong>بازی خودکار و چیدمان</strong><p>حالت کشورها بدون بیننده یا لایک، تاس و گردونه را اجرا می‌کند؛ امتیاز = عدد تاس + تعداد گیفت + امتیاز شروع جایگاه. در حالت تیمی حرکت با کامنت باقی می‌ماند.</p><div class="map-row"><label><input id="autoPlay" type="checkbox" checked> حرکت خودکار در حالت گیفت</label><label><input id="autoRestart" type="checkbox" checked> دور جدید ۱۴ ثانیه پس از جشن برد</label><button id="shuffleCountries" type="button">🎲 جابه‌جایی تصادفی کشورها</button><button id="newRoundNow">شروع دور بعد اکنون</button><button id="rollCurrent">تاس تیم نوبت‌دار</button></div><div class="map-row"><label><input id="removeInactive" type="checkbox" checked> حذف خودکار کشورهای بی‌فعالیت</label><label>مهلت بی‌فعالیتی (ثانیه) <input id="idleSeconds" type="number" min="60" max="1800" step="30" value="180"></label><button id="saveAutomation">ذخیره تنظیمات خودکار</button></div><p>هر کشور منتظر پس از ۶۰ ثانیه بدون گیفت با ذخیره عوض می‌شود. کشور منتظر با امتیاز بالاتر از ضعیف‌ترین کشور وارد بازی می‌شود. گیفت‌ها به جایگاه وصل‌اند. رز امتیاز شروع صفر و دیگر گوشه‌ها ۳ دارند. هر دور ۸ تاس برای هر کشور است و بالاترین امتیاز برنده می‌شود. حذف خودکار داخل بازی فقط برای کشورها در حالت گیفت است. زمان از اولین گیفت یا کامنت شروع می‌شود؛ هر مشارکت مهلت همان کشور را تمدید می‌کند. اگر همه حذف شوند، از پنل کشورها را برگردانید. تیم‌ها خودکار حذف نمی‌شوند.</p><div class="map-row"><span>ستون لایکر و گیفتر:</span><button id="railSplit">دو طرف — لایک چپ، گیفت راست</button><button id="railLeft">◀ سمت چپ</button><button id="railRight">سمت راست ▶</button></div>`;$('adminTools').prepend(automationBox);
function updateAutomationControls(){if(!$('autoPlay')||automationBox.contains(document.activeElement))return;for(const key of ['autoPlay','autoRestart','removeInactive'])$(key).checked=automation[key]!==false;$('idleSeconds').value=automation.idleSeconds||180;$('railSplit').setAttribute('aria-pressed',String(railSide==='split'));$('railLeft').setAttribute('aria-pressed',String(railSide==='left'));$('railRight').setAttribute('aria-pressed',String(railSide==='right'))}
$('saveAutomation').onclick=()=>command('set-automation',{automation:{autoPlay:$('autoPlay').checked,autoRestart:$('autoRestart').checked,removeInactive:$('removeInactive').checked,idleSeconds:Number($('idleSeconds').value)}});$('shuffleCountries').onclick=()=>command('shuffle-countries');$('newRoundNow').onclick=()=>command('new-round');$('rollCurrent').onclick=()=>command('roll-current');$('railSplit').onclick=()=>command('set-rail-side',{side:'split'});$('railLeft').onclick=()=>command('set-rail-side',{side:'left'});$('railRight').onclick=()=>command('set-rail-side',{side:'right'});
$('removeRosterEntry').onclick=()=>{const [kind,key]=$('rosterEntry').value.split(':');command('remove-entry',{kind,key:Number(key)})};$('restoreRosterEntry').onclick=()=>{const [kind,key]=$('rosterEntry').value.split(':');if(kind!=='active'){message('Select one of the four arena teams to restore.');return}command('restore-entry',{kind,key:Number(key)})};
roll=function(){command('roll-current')};reset=function(){command('new-round')};
function supportTier(g){return g>100?'dragon':g>=100?'diamond':g>=50?'gold':g>=10?'silver':'star'}
function tierLabel(g){return g>100?'🐉 DRAGON':g>=100?'◆ DIAMOND':g>=50?'✦ GOLD':g>=10?'✧ SILVER':'★ STAR'}
function livePoints(t,i){return (t.dicePoints||0)+(t.g||0)+(t.likePoints||0)+(giftMap[i]==='5655'?0:3)}
function addEmbers(container,count=7){const cloud=document.createElement('span');cloud.className='score-cloud';for(let n=0;n<count;n++){const dot=document.createElement('i');dot.style.setProperty('--n',n);cloud.append(dot)}container.append(cloud)}
function drawScoreboard(){let box=$('giftScoreboard');if(!box){box=document.createElement('section');box.id='giftScoreboard';box.className='gift-scoreboard';document.querySelector('.live-heading').after(box)}box.hidden=inputMode!=='gifts';document.body.classList.toggle('gift-game',inputMode==='gifts');box.replaceChildren();const heading=document.createElement('strong');heading.className='score-title';heading.textContent='◆ LIVE POINTS · '+(state.diceRolls||0)+' / '+Math.max(1,state.teams.filter(t=>t.active!==false).length)*8+' ROLLS';box.append(heading);const scores=state.teams.map((t,i)=>livePoints(t,i)),maximum=Math.max(1,...scores);state.teams.forEach((t,i)=>{const item=document.createElement('div');item.className='country-score tier-'+supportTier(t.g||0)+(t.active===false?' score-inactive':'');item.style.setProperty('--score-color',colors[i]);item.style.setProperty('--support-boost',Math.min(40,3+Math.log2(1+(t.g||0))*5)+'px');const name=document.createElement('strong');name.textContent=entryName(t,i+1);if(rosterMode==='countries')name.prepend(countryFlag(t.flag,t.name));const value=document.createElement('b');const emblem=(t.g||0)>100?'🐉':t.g>=100?'💎':t.g>=50?'🥇':t.g>=10?'🥈':'★';value.textContent=emblem+' '+compactCount(scores[i]);value.title=String(scores[i])+' points';const track=document.createElement('div');track.className='score-track';const fill=document.createElement('i');fill.style.width=(scores[i]/maximum*100)+'%';track.append(fill);const details=document.createElement('small');details.textContent='DICE '+(t.dicePoints||0)+' + GIFT '+compactCount(t.g||0)+' + LIKE '+compactCount(t.likePoints||0)+(giftMap[i]==='5655'?'':' + BASE 3');const tier=document.createElement('span');tier.className='support-tier';tier.textContent=tierLabel(t.g||0)+(t.g<10?' '+('★'.repeat(Math.min(4,t.g||0))||'☆☆☆☆'):'');item.append(name,value,track,details,tier);if(t.g>0)addEmbers(item);box.append(item)})}

function drawTurnStatus(){let el=$('liveTurnStatus');if(!el){el=document.createElement('div');el.id='liveTurnStatus';el.className='live-turn-status';document.querySelector('.arena-head').after(el)}const i=state.motion?.team??state.turn,t=state.teams[i];el.style.setProperty('--turn-color',colors[i]);if(state.winner!==null){const seconds=Math.max(0,Math.ceil(((state.nextGameAt||Date.now())-Date.now())/1000));el.textContent='🏆 '+entryName(state.teams[state.winner],state.winner+1)+' WINS'+(automation.autoRestart!==false?' · NEXT ROUND '+seconds+'s':'')}else if(!state.teams.some(t=>t.active!==false))el.textContent='NO ACTIVE TEAMS · RESTORE IN SETTINGS';else el.textContent='➤ '+entryName(t,i+1).toUpperCase()+' · '+(state.motion?.phase==='roll'?'SPINNING…':state.motion?.phase==='move'?(inputMode==='gifts'?'+'+state.motion.dice+' POINTS':'MOVING'):inputMode==='gifts'?(automation.autoPlay!==false?'AUTO TURN':'PAUSED'):'COMMENT '+(i+1))}
drawScoreboard();drawTurnStatus();drawCountryWheel();decorateWaitingGifts();renderLikers([]);updateAutomationControls();

var lastWheelRoll,lastWheelAward,wheelRotation=0;
function drawCountryWheel(){let stage=$('countryWheel');if(!stage){stage=document.createElement('div');stage.id='countryWheel';stage.className='wheel-showcase';stage.innerHTML='<div class="wheel-aura"></div><span class="wheel-pointer">▼</span><div class="wheel-disc"></div><div class="wheel-die"></div><div class="wheel-result"></div><div class="wheel-caption">AUTOMATIC DICE · NO GIFT REQUIRED</div><div class="wheel-winner" hidden></div>';const disc=stage.querySelector('.wheel-disc');for(let n=1;n<=6;n++){const label=document.createElement('b');label.className='wheel-number';label.style.setProperty('--angle',(n-1)*60+'deg');label.textContent=n;disc.append(label)}document.querySelector('.board-wrap').append(stage)}stage.hidden=inputMode!=='gifts';if(inputMode!=='gifts')return;const m=state.motion,index=m?.team??state.turn;stage.style.setProperty('--wheel-color',colors[index]);const die=stage.querySelector('.wheel-die');die.replaceChildren($('board').querySelector('.center').cloneNode(true));die.querySelector('.center').classList.remove('dice-rolling');const result=stage.querySelector('.wheel-result');result.textContent=m?.phase==='move'?entryName(state.teams[m.team],m.team+1)+' +'+m.dice+' POINTS':m?.phase==='roll'?'SPINNING FOR '+entryName(state.teams[m.team],m.team+1):state.lastDice?'LAST ROLL · '+state.lastDice:'READY TO SPIN';let challenge=stage.querySelector('.wheel-challenge');if(!challenge){challenge=document.createElement('div');challenge.className='wheel-challenge';stage.append(challenge)}challenge.hidden=!state.challenge;stage.classList.toggle('has-challenge',!!state.challenge);if(state.challenge){challenge.replaceChildren();const avatar=document.createElement('div');avatar.className='challenge-avatar';makeAvatar(avatar,state.challenge.commenter);const label=document.createElement('strong');label.textContent='NEXT MATCH · '+state.challenge.name;challenge.append(avatar,label)}stage.classList.toggle('is-spinning',m?.phase==='roll');if(m?.phase==='roll'&&lastWheelRoll!==m.id){lastWheelRoll=m.id;const disc=stage.querySelector('.wheel-disc');const from=wheelRotation||0;wheelRotation=Math.ceil(from/360)*360+720-(m.dice-1)*60;disc.animate?.([{transform:'rotate('+from+'deg)'},{transform:'rotate('+wheelRotation+'deg)'}],{duration:1500,easing:'cubic-bezier(.12,.7,.12,1)',fill:'forwards'})}if(m?.phase==='move'&&lastWheelAward!==m.id){lastWheelAward=m.id;const flight=document.createElement('b');flight.className='score-flight';flight.textContent='+'+m.dice;stage.append(flight);const from=stage.getBoundingClientRect(),to=$('player-frame-'+m.team).getBoundingClientRect(),scale=document.querySelector('main').getBoundingClientRect().width/1080;flight.animate?.([{opacity:1,transform:'translate(-50%,-50%) scale(1.6)'},{opacity:0,transform:'translate('+((to.x+to.width/2-from.x-from.width/2)/scale)+'px,'+((to.y+to.height/2-from.y-from.height/2)/scale)+'px) scale(.5)'}],{duration:900,easing:'ease-out'});setTimeout(()=>flight.remove(),950)}const winner=stage.querySelector('.wheel-winner');winner.hidden=state.winner===null;if(state.winner!==null){const team=state.teams[state.winner];winner.replaceChildren();const face=document.createElement('div');face.className='wheel-winner-face';makeAvatar(face,team.supporter||{name:entryName(team,state.winner+1),avatar:team.teamAvatar});const label=document.createElement('strong');label.textContent='🏆 '+entryName(team,state.winner+1)+' WINS';winner.append(face,label)}}
function decorateWaitingGifts(){if(inputMode!=='gifts')return;const rows=[...document.querySelectorAll('.queue-row')],entries=state.queue.slice().sort((a,b)=>(b.requests||0)-(a.requests||0)||((b.g||0)+(b.dicePoints||0))-((a.g||0)+(a.dicePoints||0))||a.requestId-b.requestId).slice(0,5);rows.forEach((row,i)=>{row.querySelector('.queue-gift')?.remove();const entry=entries[i];if(!entry)return;const preset=oneCoinGifts.find(g=>g.id===waitingGiftMap[i]);const gift=document.createElement('div');gift.className='queue-gift';const icon=document.createElement('b');icon.textContent=preset?.symbol||'🎁';const label=document.createElement('span');label.textContent=(preset?.name||'Gift')+' · 1 COIN';gift.append(icon,label);row.insertBefore(gift,row.querySelector('.request-count'));row.querySelector('.request-count').textContent='◆ '+compactCount((entry.g||0)+(entry.dicePoints||0));row.classList.add('tier-'+supportTier(entry.g||0));row.querySelector('.qcontent small').textContent='RANK '+(i+1)+' · '+(entry.g||0)+' GIFTS · COMMENT '+entry.requestId})}

const waitingGiftAdmin=document.createElement('section');waitingGiftAdmin.id='waitingGiftAdmin';waitingGiftAdmin.className='automation-controls';waitingGiftAdmin.innerHTML='<strong>گیفت‌های ثابت پنج جایگاه انتظار</strong><p>هر گیفت، کشورِ همان ردیف را حمایت می‌کند. کشورها عوض می‌شوند؛ گیفت جایگاه ثابت است. برای ورود باید امتیاز کشور منتظر از ضعیف‌ترین کشور داخل بیشتر شود.</p><div id="waitingGiftRows"></div>';$('adminTools').append(waitingGiftAdmin);
function updateWaitingGiftAdmin(){const box=$('waitingGiftRows');if(!box)return;box.replaceChildren();waitingGiftMap.forEach((id,i)=>{const preset=oneCoinGifts.find(g=>g.id===id);const row=document.createElement('div');row.className='map-row';const label=document.createElement('span');label.textContent='ردیف '+(i+1)+' · '+(preset?.symbol||'🎁')+' '+(preset?.name||id)+' · 1 COIN';const test=document.createElement('button');test.textContent='آزمایش گیفت این ردیف';test.onclick=()=>command('demo-gift',{corner:i+4,count:1});row.append(label,test);box.append(row)})}updateWaitingGiftAdmin();

const countryJoinCallout=document.createElement('div');countryJoinCallout.className='country-join-callout';countryJoinCallout.innerHTML='<strong><span class="join-main">comment your country</span> <span class="join-support">and support</span></strong>';document.querySelector('.board-wrap').append(countryJoinCallout);
function updateAudiencePosition(){const main=document.querySelector('main'),wheel=$('countryWheel');if(!wheel||inputMode!=='gifts')return;const frame=main.getBoundingClientRect(),stage=wheel.getBoundingClientRect(),scale=frame.width/1080;main.style.setProperty('--audience-top',((stage.top-frame.top)/scale+38)+'px')}
window.addEventListener('resize',()=>requestAnimationFrame(updateAudiencePosition));const glassRender=render;render=function(){glassRender();requestAnimationFrame(updateAudiencePosition)};requestAnimationFrame(updateAudiencePosition);

unlockGameAudio();

let victoryController;
function syncVictory(){if(!victoryController)return;const winner=state.winner,team=winner===null?null:state.teams[winner];victoryController.update({winner,round:state.round,until:state.nextGameAt,country:team?entryName(team,winner+1):'',person:team?.supporter||team?.commenter||team?.latestSupporter,gifts:team?.g||0,points:team?livePoints(team,winner):0})}
import('/victory.js').then(({createVictoryEffect})=>{victoryController=createVictoryEffect(document.querySelector('main'),{audio:()=>gameAudio,volume:()=>Number($('volume').value)});syncVictory()}).catch(error=>console.warn('Victory frames could not load:',error.message));
const beforeVictoryRender=render;render=function(){beforeVictoryRender();syncVictory()};
